# Use previously-fetched all_threads if available
print('all_threads_present', 'all_threads' in globals(), 'len', (len(all_threads) if 'all_threads' in globals() else None))

# Load decisions CSV (manually parse)
dec_csv = apis.file_system.show_file(access_token=fs_token, file_path='~/documents/work/recruitingdecisions.csv')['content']
lines = [ln.strip() for ln in dec_csv.splitlines() if ln.strip()]
header = lines[0]
rows = lines[1:]
# Expect header: candidate_first_name,candidate_last_name,decision
print('decisions_lines', len(rows))

decisions = []
for r in rows:
    parts = [p.strip() for p in r.split(',')]
    if len(parts) != 3:
        print('unexpected_row_parts', parts)
        continue
    decisions.append({'candidate_first_name': parts[0], 'candidate_last_name': parts[1], 'decision': parts[2]})

print('decisions', decisions)

# Build mapping candidate full name -> decision
cand_to_dec = { (d['candidate_first_name'].strip()+' '+d['candidate_last_name'].strip()).lower(): d['decision'] for d in decisions }
print('cand_to_dec_count', len(cand_to_dec))

# Search in all_threads by participant name
matches = {name: [] for name in cand_to_dec}
for t in all_threads:
    for p in t.get('participants', []):
        email = p.get('email','').lower()
        name = p.get('name','').strip().lower()
        if not name or email=='dav.mart@gmail.com':
            continue
        if name in matches:
            matches[name].append(t)

# Print matches counts
for full_name, dec in cand_to_dec.items():
    print('candidate', full_name, 'decision', dec, 'threads', len(matches[full_name]), 'thread_ids', [tt['email_thread_id'] for tt in matches[full_name]])

# Also print threads whose subject or preview contains last names (fallback)
last_names = set(d['candidate_last_name'].lower() for d in decisions)
rev_matches = {ln: [] for ln in last_names}
for t in all_threads:
    subj = (t.get('subject') or '').lower()
    prev = (t.get('preview') or '').lower()
    for ln in last_names:
        if ln in subj or ln in prev:
            rev_matches[ln].append(t)

print('fallback_lastname_counts', {ln: len(ts) for ln, ts in rev_matches.items()})
for ln in sorted(rev_matches.keys()):
    if rev_matches[ln]:
        print('last name', ln, 'thread_ids_sample', [tt['email_thread_id'] for tt in rev_matches[ln][:5]])

